const j122Car = (x, y, s, c = "#ef4444") => grp(x, y, s, `<path d="M-32 6 L-32 -6 Q-31 -12 -22 -12 L-14 -24 Q-12 -26 -8 -26 L12 -26 Q16 -26 18 -22 L24 -12 Q32 -12 33 -4 L33 6 Z" fill="${c}"/><path d="M-11 -22 L-3 -22 L-3 -13 L-16 -13 Z" fill="#bfe6ff"/><path d="M1 -22 L13 -22 L19 -13 L1 -13 Z" fill="#bfe6ff"/><circle cx="-18" cy="7" r="7" fill="#374151"/><circle cx="18" cy="7" r="7" fill="#374151"/><circle cx="-18" cy="7" r="2.8" fill="#cbd5e1"/><circle cx="18" cy="7" r="2.8" fill="#cbd5e1"/>`);
const j122Win = (x, y, cols, rows, dx, dy, c = "#bfe6ff") => { let s = ""; for(let r = 0; r < rows; r++) for(let k = 0; k < cols; k++) s += `<rect x="${x + k * dx}" y="${y + r * dy}" width="8" height="8" rx="1" fill="${c}"/>`; return s; };
const j122Tears = (x, y) => `<path d="M${x} ${y} C${x - 3} ${y + 5} ${x - 3} ${y + 8} ${x} ${y + 8} C${x + 3} ${y + 8} ${x + 3} ${y + 5} ${x} ${y} Z" fill="#60a5fa"/><path d="M${x + 22} ${y} C${x + 19} ${y + 5} ${x + 19} ${y + 8} ${x + 22} ${y + 8} C${x + 25} ${y + 8} ${x + 25} ${y + 5} ${x + 22} ${y} Z" fill="#60a5fa"/>`;
const j122Train = (x, y, s, c = "#2f6fde", stripe = "#ffd23f") => grp(x, y, s, `<rect x="-46" y="-24" width="92" height="34" rx="9" fill="${c}"/><rect x="-46" y="2" width="92" height="5" fill="${stripe}"/>${[-38, -20, -2, 16].map(xx => `<rect x="${xx}" y="-17" width="13" height="12" rx="2" fill="#bfe6ff"/>`).join("")}<rect x="32" y="-17" width="9" height="16" rx="2" fill="#e0f2fe"/><circle cx="-30" cy="12" r="4.5" fill="#374151"/><circle cx="-14" cy="12" r="4.5" fill="#374151"/><circle cx="14" cy="12" r="4.5" fill="#374151"/><circle cx="30" cy="12" r="4.5" fill="#374151"/>`);
const j122Rails = (y) => `<rect x="0" y="${y}" width="160" height="4" fill="#9ca3af"/>` + [0, 1, 2, 3, 4, 5, 6, 7].map(i => `<rect x="${4 + i * 20}" y="${y + 4}" width="10" height="3" fill="#a16207"/>`).join("");

