  museum: () => svgWrap("#f3f0ea", ground("#e2dccd") + `<path d="M24 40 L80 16 L136 40 Z" fill="#c2b59b"/><rect x="26" y="40" width="108" height="6" fill="#d6ccb4"/>` + [34, 56, 78, 100, 120].map(xx => `<rect x="${xx}" y="46" width="8" height="48" fill="#ebe4d3" stroke="#c2b59b"/>`).join("") + `<rect x="22" y="94" width="116" height="8" fill="#d6ccb4"/>` + txt(80, 36, "MUSEUM", 9, "#6b5b3e")),
  beach: () => svgWrap("#cfeeff", `<rect x="0" y="62" width="160" height="22" fill="#38bdf8"/><path d="M0 64 Q20 60 40 64 T80 64 T120 64 T160 64" stroke="#fff" stroke-width="2" fill="none"/><path d="M0 84 Q80 76 160 84 L160 120 L0 120 Z" fill="#fde7a8"/>` + O.sun(30, 28, .8) + O.umbrella(112, 76, .8) + O.ball(54, 100, 1)),
  library: () => svgWrap("#f2efff", `<rect x="8" y="16" width="70" height="88" rx="3" fill="#a86d36"/>` + [24, 52, 80].map(yy => `<rect x="12" y="${yy}" width="62" height="22" fill="#fdf5ea"/>` + ["#ef4444", "#3b82f6", "#22c55e", "#f59e0b", "#a855f7", "#ec4899"].map((c, i) => `<rect x="${15 + i * 9.5}" y="${yy + 4 - (i % 2) * 2}" width="7" height="${18 - 4 + (i % 2) * 2}" rx="1" fill="${c}"/>`).join("")).join("") + kid(120, {pose:"hold", mood:"smile"}) + O.openBook(120, 86, .5)),
